CREATE TABLE IF NOT EXISTS project_economic_scenarios (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), economic_model_id uuid NOT NULL REFERENCES project_economic_models(id) ON DELETE CASCADE, scenario_name text NOT NULL, revenue_multiplier numeric(8,4) NOT NULL DEFAULT 1, cost_multiplier numeric(8,4) NOT NULL DEFAULT 1, exit_multiplier numeric(8,4) NOT NULL DEFAULT 1, projected_profit numeric(20,2), projected_margin numeric(8,4), assumptions jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());